import type { Language } from "../agent/config.js";
import type { VoiceMeter } from "../render/voiceMeter.js";

// Pre-recorded lines the live game plays, see docs/redqueen-voicelines.md.
// The files are generated by `npm run voicelines`.
export const VOICE_LINES = {
  vialRemoved: ["SYS_01_VIAL_REMOVED"],
  escalating: ["SYS_02_ESCALATING"],
  vialReturned: ["SYS_03_VIAL_RETURNED"],
  sealFailure: ["SYS_04_SEAL_FAILURE"],
  intro: ["RQ_01_INTRO"],
  fail: ["RQ_19_FAIL"],
  reset: ["RQ_20_RESET"],
};

// Time warnings, played once each when the remaining time drops to `secondsLeft`.
export const WARNINGS = [
  { secondsLeft: 60, line: "RQ_15_60S" },
  { secondsLeft: 30, line: "RQ_16_30S" },
  { secondsLeft: 10, line: "RQ_17_10S" },
];

export function voiceLineUrl(language: Language, id: string): string {
  return `/voicelines/${language}/${id}.mp3`;
}

// Plays pre-recorded lines one after another, through the voice meter so the hologram reacts.
export class VoiceLinePlayer {
  language: Language = "en";
  private current?: HTMLAudioElement;
  private stopped = false;

  constructor(private readonly meter: VoiceMeter) {}

  // Resolves when all lines have played, or when stop() was called.
  async play(ids: readonly string[]) {
    this.stopped = false;
    for (const id of ids) {
      if (this.stopped) return;
      await this.playOne(id);
    }
  }

  stop() {
    this.stopped = true;
    this.current?.pause();
    this.current?.dispatchEvent(new Event("ended"));
  }

  get playing(): boolean {
    return this.current !== undefined;
  }

  private playOne(id: string): Promise<void> {
    const audio = new Audio(voiceLineUrl(this.language, id));
    this.current = audio;
    this.meter.connectElement(audio);
    return new Promise((resolve) => {
      const done = () => {
        if (this.current === audio) this.current = undefined;
        resolve();
      };
      audio.addEventListener("ended", done, { once: true });
      audio.addEventListener("error", () => {
        console.warn(`Voice line ${audio.src} missing, run npm run voicelines`);
        done();
      }, { once: true });
      audio.play().catch(done);
    });
  }
}
